// fileNeedsUpdate checks if a file has been modified since indexing. It errors when the
// file cannot be read or its stored hash cannot be fetched; callers count the file failed.
func (m *IndexManager) fileNeedsUpdate(ctx context.Context, filePath string) (bool, error) {
	// Get file content
	content, err := os.ReadFile(filePath)
	if err != nil {
		return false, err
	}

	// Calculate current content hash
	hash := sha256.Sum256(content)
	currentHash := hex.EncodeToString(hash[:])

	// Get stored hash for this file
	// A store that cannot say is an error, not "needs indexing": re-indexing would hide it.
	storedHash, err := m.storage.GetFileHash(ctx, filePath)
	if err != nil {
		return false, fmt.Errorf("failed to read stored hash: %w", err)
	}

	if storedHash == "" {
		return true, nil // No stored hash = needs indexing
	}

	// Compare hashes - file needs update if hashes differ
	return storedHash != currentHash, nil
}

// indexPerFile processes files one at a time (original behavior)
func (m *IndexManager) indexPerFile(ctx context.Context, files []string, opts IndexOptions, result *IndexResult) (*IndexResult, error) {
	totalFiles := len(files)

	for i, file := range files {
		select {
		case <-ctx.Done():
			return result, ctx.Err()
		default:
		}

		// Check if file is already indexed and unchanged (for resume capability)
		if !opts.Force {
			needsIndex, err := m.fileNeedsUpdate(ctx, file)
			if err != nil {
				// An unreadable file is not indexed; counting it unchanged would hide that.
				result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", file, err))
				result.FilesSkipped++
				if opts.OnProgress != nil {
					opts.OnProgress(ProgressEvent{
						Current:     i + 1,
						Total:       totalFiles,
						FilePath:    file,
						ChunksTotal: result.ChunksCreated,
						Skipped:     true,
					})
				}
				continue
			}
			if !needsIndex {
				result.FilesUnchanged++
				// Report progress for skipped file
				if opts.OnProgress != nil {
					opts.OnProgress(ProgressEvent{
						Current:     i + 1,
						Total:       totalFiles,
						FilePath:    file,
						ChunksTotal: result.ChunksCreated,
						Skipped:     true,
					})
				}
				continue
			}
		}

		// Process the file
		processErr := m.processFile(ctx, file, result, opts.BatchSize, opts.Parallel, opts.Domain)
		if processErr != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("%s: %v", file, processErr))
			result.FilesSkipped++
		} else {
			result.FilesProcessed++
		}

		// Report progress
		if opts.OnProgress != nil {
			opts.OnProgress(ProgressEvent{
				Current:     i + 1,
				Total:       totalFiles,
				FilePath:    file,
				ChunksTotal: result.ChunksCreated,
				Skipped:     false,
			})
		}
	}

	return result, nil
}

